-- ============================================================
-- Schema: core.assessment_questions (bilingual: EN + VI)
-- Columns: prompt_en, prompt_vi (adjacent)
-- options_json: 'options' (EN) + 'options_vi' (VI)
-- ============================================================

CREATE TABLE IF NOT EXISTS core.assessment_questions
(
    id            bigint  NOT NULL DEFAULT nextval('core.assessment_questions_id_seq'::regclass),
    form_id       bigint,
    question_no   integer,
    question_key  text,
    prompt_en     text    NOT NULL,
    prompt_vi     text    NOT NULL,
    options_json  jsonb,
    reverse_score boolean DEFAULT false,
    created_at    timestamp with time zone DEFAULT now(),
    CONSTRAINT assessment_questions_pkey PRIMARY KEY (id),
    CONSTRAINT uq_assessment_questions_form_no UNIQUE (form_id, question_no),
    CONSTRAINT assessment_questions_form_id_fkey
        FOREIGN KEY (form_id) REFERENCES core.assessment_forms(id)
        ON UPDATE NO ACTION ON DELETE CASCADE
);

-- ── MIGRATION NOTES ─────────────────────────────────────────────────────
-- Old column removed: prompt
-- New columns: prompt_en (original EN), prompt_vi (translated VI)
-- options_json now has 'options' (EN) and 'options_vi' (VI)
-- to_client() should pick prompt_en or prompt_vi based on user lang

-- ── SEED DATA ────────────────────────────────────────────────────────────
TRUNCATE core.assessment_questions RESTART IDENTITY CASCADE;
